import { APIExecutor, createAPIContext, defineOperation } from "@zudojs/api";

const steps = [];
const log = {
  async intercept(call, next) {
    steps.push("log in");
    const result = await next();
    steps.push("log out");
    return result;
  },
};
const auth = {
  async intercept(call, next) {
    steps.push("auth");
    return next();
  },
};
const op = defineOperation({ name: "tasks.list", handler: async () => { steps.push("handler"); return []; } });
await new APIExecutor({ interceptors: [log, auth] }).execute(op, {}, createAPIContext("r1", {}));
console.log(steps.join(" > "));

import { APIAuthenticationError, APIExecutor, apiFailure, createAPIContext, defineOperation, UserIdContextKey } from "@zudojs/api";

let handlerRuns = 0;
const requireUser = {
  async intercept(call, next) {
    if (call.context.get(UserIdContextKey) === undefined) {
      return apiFailure(new APIAuthenticationError("Sign in first."));
    }
    return next();
  },
};
const op = defineOperation({ name: "tasks.list", handler: async () => { handlerRuns += 1; return []; } });
const executor = new APIExecutor({ interceptors: [requireUser] });
const anonymous = await executor.execute(op, {}, createAPIContext("r1", {}));
const signedIn = createAPIContext("r2", {});
signedIn.set(UserIdContextKey, "ada");
const ada = await executor.execute(op, {}, signedIn);
console.log(anonymous.error.statusCode, ada.ok, handlerRuns);

