import { APIAuthenticationError, APIExecutor, APIOperationRegistry, apiFailure, bindApiQueue, defineOperation } from "@zudojs/api";
import { createInMemoryQueue, createQueueName } from "@zudojs/queue";

const requireUser = {
  async intercept(call, next) {
    if (typeof call.context.state.userId !== "string") return apiFailure(new APIAuthenticationError("Sign in first."));
    return next();
  },
};
const registry = new APIOperationRegistry();
registry.register(defineOperation({ name: "tasks.create", handler: async (input) => input.title }));
const queue = createInMemoryQueue(createQueueName("operations"));
bindApiQueue(queue, registry, {
  executor: new APIExecutor({ interceptors: [requireUser] }),
  state: (job) => ({ userId: typeof job.metadata?.userId === "string" ? job.metadata.userId : undefined }),
});
queue.events?.on("job:completed", ({ result }) => console.log("completed", result));
queue.events?.on("job:failed", ({ error }) => console.log("failed", error.message));
await queue.add("tasks.create", { title: "Water plants" }, { attempts: 1, metadata: { userId: "ada" } });
await queue.add("tasks.create", { title: "Walk the dog", userId: "ada" }, { attempts: 1 });
await new Promise((resolve) => setTimeout(resolve, 200));
await queue.close();
